function getPrice(string datasource) oraclizeAPI internal returns (uint){
        uint price = oraclize.getPrice(datasource);
        if (price > 1 ether + tx.gasprice*200000) return 0; 
        return price;
    }

function query(string datasource, string arg) oraclizeAPI internal returns (bytes32 id){
        uint price = oraclize.getPrice(datasource);
        if (price > 1 ether + tx.gasprice*200000) return 0; 
        return oraclize.query.value(price)(0, datasource, arg);
    }

